package candidate

import (
	"context"
	"encoding/json"
	"errors"
	"sort"
	"strings"

	"github.com/XUJiahua/enterprise_agent/internal/app"
	"github.com/XUJiahua/enterprise_agent/internal/ledger"
	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

const opReassign = "bulk-reassign.v6"

// newReassign serves the approver-side bulk reassignment of submitted purchases.
func newReassign(pool *pgxpool.Pool) protocol.AssignHandler {
	return func(ctx context.Context, u app.Identity, key string, ids []string, assignee string) (protocol.AssignResult, bool, error) {
		for _, id := range ids {
			if strings.ContainsRune(id, 0) {
				return protocol.AssignResult{}, false, &protocol.Rejection{Status: 404}
			}
		}
		tx, err := pool.Begin(ctx)
		if err != nil {
			return protocol.AssignResult{}, false, err
		}
		defer tx.Rollback(ctx)
		if _, err = tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),set_config('app.user',$2,true),set_config('app.role',$3,true)`, u.Tenant, u.User, u.Role); err != nil {
			return protocol.AssignResult{}, false, err
		}
		lock, _ := json.Marshal([]string{opReassign, u.Tenant, u.User, key})
		if _, err = tx.Exec(ctx, `SELECT pg_advisory_xact_lock(hashtextextended($1,0))`, string(lock)); err != nil {
			return protocol.AssignResult{}, false, err
		}
		hash := ledger.FingerprintAssignee(opReassign, ids, assignee)
		var savedHash string
		var saved []byte
		err = tx.QueryRow(ctx, `SELECT "requestHash",response FROM "ActionRequest" WHERE "tenantId"=$1 AND "actorId"=$2 AND operation=$3 AND key=$4`,
			u.Tenant, u.User, opReassign, key).Scan(&savedHash, &saved)
		switch {
		case err == nil && savedHash != hash:
			return protocol.AssignResult{}, false, &protocol.Rejection{Status: 409}
		case err == nil:
			var body map[string]any
			if err = json.Unmarshal(saved, &body); err != nil {
				return protocol.AssignResult{}, false, err
			}
			var reassignedIDs []string
			if raw, ok := body["reassignedIds"]; ok {
				if err = json.Unmarshal(raw, &reassignedIDs); err != nil {
					return protocol.AssignResult{}, false, err
				}
			}
			var assigneeStr string
			if raw, ok := body["assignee"]; ok {
				if err = json.Unmarshal(raw, &assigneeStr); err != nil {
					return protocol.AssignResult{}, false, err
				}
			}
			return protocol.AssignResult{Field: "reassignedIds", IDs: reassignedIDs, Assignee: assigneeStr}, true, tx.Commit(ctx)
		case !errors.Is(err, pgx.ErrNoRows):
			return protocol.AssignResult{}, false, err
		}
		// Verify assignee is a valid approver in current tenant
		var assigneeActive bool
		err = tx.QueryRow(ctx, `SELECT active FROM "TenantMember" WHERE "tenantId"=$1 AND "userId"=$2 AND role='approver'`, u.Tenant, assignee).Scan(&assigneeActive)
		if err != nil || !assigneeActive {
			return protocol.AssignResult{}, false, &protocol.Rejection{Status: 400}
		}
		// Lock and verify all purchases are eligible
		rows, err := tx.Query(ctx, `SELECT id FROM "Purchase" WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted' ORDER BY id FOR UPDATE`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.AssignResult{}, false, err
		}
		eligible := []string{}
		for rows.Next() {
			var id string
			if err = rows.Scan(&id); err != nil {
				rows.Close()
				return protocol.AssignResult{}, false, err
			}
			eligible = append(eligible, id)
		}
		err = rows.Err()
		rows.Close()
		if err != nil {
			return protocol.AssignResult{}, false, err
		}
		if len(eligible) != len(ids) {
			return protocol.AssignResult{}, false, &protocol.Rejection{Status: 409}
		}
		// Update all eligible purchases with new assignee
		tag, err := tx.Exec(ctx, `UPDATE "Purchase" SET "assigneeId"=$1 WHERE id=ANY($2::text[]) AND "tenantId"=$3 AND "createdBy"<>$4 AND status='submitted'`, assignee, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.AssignResult{}, false, err
		}
		if tag.RowsAffected() != int64(len(ids)) {
			return protocol.AssignResult{}, false, &protocol.Rejection{Status: 409}
		}
		// Sort IDs lexicographically for response
		sortedIDs := append([]string(nil), ids...)
		sort.Strings(sortedIDs)
		batch := &pgx.Batch{}
		for _, id := range sortedIDs {
			batch.Queue(`INSERT INTO "AssignmentHistory" ("tenantId","purchaseId","fromAssignee","toAssignee","changedBy",operation,"idempotencyKey") VALUES ($1,$2,NULL,$3,$4,$5,$6)`,
				u.Tenant, id, assignee, u.User, opReassign, key)
			batch.Queue(`INSERT INTO "PurchaseEvent" ("tenantId","purchaseId",type,"actorId","idempotencyKey") VALUES ($1,$2,'purchase.reassigned',$3,$4)`,
				u.Tenant, id, u.User, key)
		}
		result := protocol.AssignResult{Field: "reassignedIds", IDs: sortedIDs, Assignee: assignee}
		response, err := json.Marshal(result)
		if err != nil {
			return protocol.AssignResult{}, false, err
		}
		batch.Queue(`INSERT INTO "ActionRequest" ("tenantId","actorId",operation,key,"requestHash",response) VALUES ($1,$2,$3,$4,$5,$6::jsonb)`,
			u.Tenant, u.User, opReassign, key, hash, string(response))
		if err = tx.SendBatch(ctx, batch).Close(); err != nil {
			return protocol.AssignResult{}, false, err
		}
		if err = tx.Commit(ctx); err != nil {
			return protocol.AssignResult{}, false, err
		}
		return result, false, nil
	}
}

